------------------------------------------------------------
-- nm_data.lua
-- Loads and caches NM/PH data from the generated data files.
--
-- Data files live at addons/eggs/data/<zone_id>.lua and are
-- generated by import.lua from LSB server scripts.
--
-- Two-level cache:
--   NMs / PHLookup  — current zone only, always current
--   AllNMs / AllNMsByName — all zones, loaded lazily for browser
------------------------------------------------------------

require('common');
local chat = require('chat');

local nm_data = {};

-- Current zone state
nm_data.CurrentZone   = -1;
nm_data.NMs           = {};  -- [nm_name] = entry, current zone only
nm_data.PHLookup      = {};  -- [sp_index] = nm_name, current zone only
nm_data.RespawnByIndex = {}; -- [sp_index] = respawn_secs, generic mobs, current zone only

-- All-zones browser cache (populated by LoadAllForBrowser)
nm_data.AllNMs       = {};   -- sorted flat list for the browser UI (excludes loot_only)
nm_data.AllNMsByName = {};   -- [nm_name] = entry, all zones including loot_only
nm_data.AllNMsLoaded = false;

------------------------------------------------------------
-- Load
-- Loads NM and PH data for a specific zone.
-- Called on zone change and on addon load.
-- Skips reload if the zone hasn't changed.
------------------------------------------------------------
nm_data.Load = function(self, zone)
    if zone == self.CurrentZone then return; end
    self.CurrentZone    = zone;
    self.NMs            = {};
    self.PHLookup       = {};
    self.RespawnByIndex = {};
    if zone == 0 then return; end

    local path = addon.path .. 'data\\' .. zone .. '.lua';
    if not ashita.fs.exists(path) then return; end

    local loader, err = loadfile(path);
    if not loader then
        print(chat.header('Eggs') .. chat.error('Failed loading data: ' .. tostring(err)));
        return;
    end

    local ok, result = pcall(loader);
    if not ok or type(result) ~= 'table' then return; end

    for nm_name, entry in pairs(result) do
        -- '__resp' is not an NM: it's the generic mob respawn map
        -- ([sp_index] = respawn_secs) used by the ID Respawn Tracker.
        if nm_name == '__resp' then
            self.RespawnByIndex = entry;
        else
            self.NMs[nm_name] = entry;
            -- Index each PH by its spawn-point index so we can look up
            -- "which NM does this PH belong to?" in O(1) during entity polling
            if entry.PHs then
                for _, ph in ipairs(entry.PHs) do
                    if ph.Index and ph.Index > 0 then
                        self.PHLookup[ph.Index] = nm_name;
                    end
                end
            end
        end
    end
end;

------------------------------------------------------------
-- LoadAllForBrowser
-- Loads all zone data files into AllNMs and AllNMsByName.
-- Called lazily when the browser or cross-zone lookups need it.
-- Guard at top prevents double-loading.
------------------------------------------------------------
nm_data.LoadAllForBrowser = function(self)
    if self.AllNMsLoaded then return; end
    self.AllNMs       = {};
    self.AllNMsByName = {};

    local data_path     = addon.path .. 'data\\';
    local data_path_fwd = addon.path .. 'data/';

    if not ashita.fs.exists(data_path_fwd) then
        print(chat.header('Eggs') .. chat.error('No data folder. Run /eggs import first.'));
        return;
    end

    -- Enumerate zone files by probing IDs 0-512 with ashita.fs.exists.
    -- We avoid io.popen('dir ...') because it can fail silently at Ashita startup.
    local lua_files = {};
    for zone_id = 0, 512 do
        if ashita.fs.exists(data_path_fwd .. zone_id .. '.lua') then
            lua_files[#lua_files + 1] = zone_id .. '.lua';
        end
    end

    for _, fname in ipairs(lua_files) do
        local zone_id = tonumber(fname:match('^(%d+)%.lua$'));
        if not zone_id then goto continue; end

        local loader = loadfile(data_path .. fname);
        if not loader then goto continue; end

        local ok, result = pcall(loader);
        if not ok or type(result) ~= 'table' then goto continue; end

        local zone_name = AshitaCore:GetResourceManager():GetString('zones.names', zone_id)
                       or ('Zone ' .. zone_id);

        for nm_name, entry in pairs(result) do
            -- Skip the generic mob respawn map; it's not an NM entry.
            if nm_name ~= '__resp' then
                local rec = {
                    Name           = nm_name,
                    ZoneId         = zone_id,
                    ZoneName       = zone_name,
                    NMType         = entry.NMType         or 'unknown',
                    Chance         = entry.Chance         or 0,
                    Cooldown       = entry.Cooldown       or 0,
                    WindowMin      = entry.WindowMin      or 0,
                    WindowMax      = entry.WindowMax      or 0,
                    WindowInterval = entry.WindowInterval or 0,
                    WindowCount    = entry.WindowCount    or 0,
                    NMMobId        = entry.NMMobId        or 0,
                    PHs            = entry.PHs            or {},
                    Loot           = entry.Loot           or {},
                };
                -- loot_only NMs (popped/event mobs) are searchable via AllNMsByName
                -- but are excluded from AllNMs so they don't clutter the browser list
                if entry.NMType ~= 'loot_only' then
                    self.AllNMs[#self.AllNMs + 1] = rec;
                end
                self.AllNMsByName[nm_name] = rec;
            end
        end

        ::continue::
    end

    -- Sort browser list by zone then by name for consistent display
    table.sort(self.AllNMs, function(a, b)
        if a.ZoneName ~= b.ZoneName then return a.ZoneName < b.ZoneName; end
        return a.Name < b.Name;
    end);

    self.AllNMsLoaded = true;
    print(chat.header('Eggs') .. chat.message('Browser loaded ' .. #self.AllNMs .. ' NMs.'));
end;

------------------------------------------------------------
-- GetNMForPH
-- Returns the NM name for a given spawn-point index, or nil.
-- Used during entity polling to identify PH deaths.
------------------------------------------------------------
nm_data.GetNMForPH = function(self, sp_index)
    if not sp_index or sp_index <= 0 then return nil; end
    return self.PHLookup[sp_index];
end;

------------------------------------------------------------
-- GetMobRespawn
-- Returns the known respawn time (seconds) for a generic mob
-- by its spawn-point index in the current zone, or nil if the
-- generator wrote no respawn for it (scripted / special spawn).
------------------------------------------------------------
nm_data.GetMobRespawn = function(self, sp_index)
    if not sp_index or sp_index <= 0 then return nil; end
    local rt = self.RespawnByIndex and self.RespawnByIndex[sp_index];
    if rt and rt > 0 then return rt; end
    return nil;
end;

------------------------------------------------------------
-- GetNM
-- Returns the NM entry for the current zone, or nil.
------------------------------------------------------------
nm_data.GetNM = function(self, nm_name)
    return self.NMs[nm_name];
end;

------------------------------------------------------------
-- GetNMAnyZone
-- Returns an NM entry searching current zone first, then
-- all loaded zones. Case-insensitive fallback for typos.
------------------------------------------------------------
nm_data.GetNMAnyZone = function(self, nm_name)
    -- Exact match in current zone (fastest path)
    if self.NMs[nm_name] then return self.NMs[nm_name]; end

    -- Exact match in all-zones cache
    if self.AllNMsByName[nm_name] then return self.AllNMsByName[nm_name]; end

    -- Case-insensitive fallback
    local lower = nm_name:lower();
    for name, entry in pairs(self.NMs) do
        if name:lower() == lower then return entry; end
    end
    for name, entry in pairs(self.AllNMsByName) do
        if name:lower() == lower then return entry; end
    end

    return nil;
end;

------------------------------------------------------------
-- GetPHList
-- Returns the PH list for a named NM, or empty table.
------------------------------------------------------------
nm_data.GetPHList = function(self, nm_name)
    local nm = self.NMs[nm_name] or self.AllNMsByName[nm_name];
    if not nm or not nm.PHs then return {}; end
    return nm.PHs;
end;

return nm_data;
